import{_ as t,o as e,c as i,a2 as l}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"下载画质只有 360P / 480P","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/low-quality-360p.md","filePath":"troubleshooting/low-quality-360p.md","lastUpdated":1783259576000}'),o={name:"troubleshooting/low-quality-360p.md"};function r(n,a,s,p,d,h){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="下载画质只有-360p-480p" tabindex="-1">下载画质只有 360P / 480P <a class="header-anchor" href="#下载画质只有-360p-480p" aria-label="Permalink to &quot;下载画质只有 360P / 480P&quot;">​</a></h1><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2><p>下载完成后视频画质很低，只有 360P 或 480P，即使选择了 1080P 或更高画质。</p><p>设置页面显示「未登录，只能下载低画质」。</p><h2 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h2><p>Bilibili 对未登录用户限制最高画质为 480P。1080P 及以上需要登录账号，大会员画质（4K、HDR、杜比）需要有效的大会员。</p><h2 id="解决" tabindex="-1">解决 <a class="header-anchor" href="#解决" aria-label="Permalink to &quot;解决&quot;">​</a></h2><ol><li>打开 yutto-uiya → 设置 → 账号状态</li><li>点击「扫码登录」</li><li>用 Bilibili 手机 App 扫描二维码</li><li>等待显示「已登录」</li><li>重新下载即可获得高画质</li></ol>',8)])])}const _=t(o,[["render",r]]);export{c as __pageData,_ as default};
